import React, { useState, useEffect } from 'react';
import QRCode from 'react-qr-code';
import { useNavigate } from 'react-router-dom';
import { useSocket } from '../context/SocketContext';
import { useTheme } from '../context/ThemeContext';
import { createSubscription } from '../services/api';
import SubscriptionToast from './SubscriptionToast';

const SubscriptionQRCode = ({ plan, onClose, onSuccess }) => {
  const navigate = useNavigate();
  const { socket } = useSocket();
  const { isDarkMode } = useTheme();
  const [upiId] = useState('amrutanshu20003-16@oksbi');
  const [qrValue, setQrValue] = useState('');
  const [countdown, setCountdown] = useState(300);
  const [copied, setCopied] = useState(false);
  const [subscriptionId, setSubscriptionId] = useState('');
  const [toast, setToast] = useState(null);

  useEffect(() => {
    // Generate subscription ID
    const subId = `SUB_${Date.now()}_${Math.random().toString(36).substr(2, 9).toUpperCase()}`;
    setSubscriptionId(subId);

    // Create UPI payment string
    const upiString = `upi://pay?pa=${upiId}&pn=MilkMitra&am=${plan.price}&cu=INR&tn=Subscription_${plan.name}_${subId}`;
    setQrValue(upiString);

    // Test toast notification (remove this after testing)
    setTimeout(() => {
      setToast({
        message: 'Test toast notification - This should be visible!',
        type: 'error'
      });
    }, 1000);

    // Create subscription in backend when QR code is shown
    createSubscriptionInBackend(subId);
  }, [plan, upiId]);

  // Create subscription in backend
  const createSubscriptionInBackend = async (subId) => {
    try {
      const subscriptionData = {
        subscriptionId: subId,
        type: 'membership',
        planType: plan.id,
        planName: plan.name,
        paymentMethod: 'online',
        pricing: {
          basePrice: plan.price,
          totalAmount: plan.price
        },
        price: plan.price,
        deliveryAddress: null // Required field but null for membership
      };

      const response = await createSubscription(subscriptionData);
      console.log('✅ Subscription created in backend:', response.data);
    } catch (error) {
      console.error('❌ Error creating subscription:', error);
      console.error('❌ Error response:', error.response);
      console.error('❌ Error status:', error.response?.status);
      console.error('❌ Error message:', error.response?.data?.message);

      // Show toast notification instead of alert
      setToast({
        message: error.response?.data?.message || 'Failed to create subscription',
        type: 'error'
      });
    }
  };

  // Poll for subscription status every 3 seconds (backup to socket)
  const fetchSubscriptionStatus = async () => {
    try {
      // This would be replaced with actual API call
      // const response = await getSubscriptionById(subscriptionId);
      // For now, we'll simulate with socket events

      console.log('🔍 Checking subscription status for:', subscriptionId);
    } catch (error) {
      console.error('Error fetching subscription status:', error);
    }
  };

  useEffect(() => {
    if (subscriptionId) {
      // Start polling for subscription status updates
      const interval = setInterval(fetchSubscriptionStatus, 3000);

      return () => {
        clearInterval(interval);
      };
    }
  }, [subscriptionId]);

  useEffect(() => {
    if (countdown > 0) {
      const timer = setTimeout(() => setCountdown(countdown - 1), 1000);
      return () => clearTimeout(timer);
    } else {
      // Auto close when timer expires
      onClose();
    }
  }, [countdown, onClose]);

  useEffect(() => {
    // Prevent scroll
    document.body.style.overflow = 'hidden';

    // Disable navbar interactions
    const navbar = document.querySelector('nav, header, .navbar, [class*="nav"]');
    if (navbar) {
      navbar.style.pointerEvents = 'none';
      navbar.style.opacity = '0.5';
    }

    // Disable all interactive elements except our modal
    const allElements = document.querySelectorAll('button, a, input, select, textarea');
    allElements.forEach(el => {
      if (!el.closest('.fixed')) {
        el.style.pointerEvents = 'none';
      }
    });

    return () => {
      document.body.style.overflow = '';
      if (navbar) {
        navbar.style.pointerEvents = '';
        navbar.style.opacity = '';
      }
      allElements.forEach(el => {
        el.style.pointerEvents = '';
      });
    };
  }, []);

  // Listen for subscription payment verification from admin
  useEffect(() => {
    if (socket) {
      console.log('🔌 Socket connected, listening for subscriptionPaymentVerified...');
      console.log('📦 Waiting for subscriptionId:', subscriptionId);

      const handleSubscriptionPaymentVerified = (data) => {
        console.log('📨 Received subscriptionPaymentVerified event:', data);
        console.log('🔍 Comparing:', data.subscriptionId, '===', subscriptionId);

        if (data.subscriptionId === subscriptionId || String(data.subscriptionId) === String(subscriptionId)) {
          console.log('✅ Subscription ID matched! Processing success...');

          // Re-enable body interactions before navigation
          document.body.style.overflow = '';
          const navbar = document.querySelector('nav, header, .navbar, [class*="nav"]');
          if (navbar) {
            navbar.style.pointerEvents = '';
            navbar.style.opacity = '';
          }

          // Call success callback
          if (onSuccess) {
            onSuccess({
              subscriptionId,
              plan,
              paymentMethod: 'online',
              amount: plan.price,
              message: 'Subscription payment verified successfully!'
            });
          }

          // Close modal
          onClose();
        } else {
          console.log('❌ Subscription ID did not match');
        }
      };

      socket.on('subscriptionPaymentVerified', handleSubscriptionPaymentVerified);

      return () => {
        socket.off('subscriptionPaymentVerified', handleSubscriptionPaymentVerified);
      };
    } else {
      console.log('⚠️ Socket not connected');
    }
  }, [socket, subscriptionId, onClose, onSuccess, plan]);

  const formatTime = (seconds) => {
    const mins = Math.floor(seconds / 60);
    const secs = seconds % 60;
    return `${mins}:${secs.toString().padStart(2, '0')}`;
  };

  const handleCopy = () => {
    navigator.clipboard.writeText(upiId);
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  const handleClose = () => {
    // Re-enable body interactions before closing
    document.body.style.overflow = '';
    const navbar = document.querySelector('nav, header, .navbar, [class*="nav"]');
    if (navbar) {
      navbar.style.pointerEvents = '';
      navbar.style.opacity = '';
    }

    onClose();
  };

  return (
    <div 
      className="fixed inset-0 bg-black/60 backdrop-blur-lg flex items-center justify-center z-[9999] p-4"
      onContextMenu={(e) => e.preventDefault()}
      style={{ display: 'flex' }}
    >
      {/* Glass background effect */}
      <div className="absolute inset-0 bg-gradient-to-br from-purple-500/10 via-blue-500/10 to-pink-500/10 backdrop-blur-sm"></div>

      <div 
        className={`relative ${isDarkMode ? 'bg-gray-900/95' : 'bg-white/95'} backdrop-blur-xl rounded-2xl p-6 max-w-md w-full mx-auto shadow-2xl border ${isDarkMode ? 'border-gray-700/50' : 'border-white/20'} max-h-[90vh] overflow-y-auto scrollbar-hide`}
        onContextMenu={(e) => e.preventDefault()}
        style={{ display: 'block' }}
      >
        <style>{`
          .scrollbar-hide::-webkit-scrollbar {
            display: none;
          }
          .scrollbar-hide {
            -ms-overflow-style: none;
            scrollbar-width: none;
          }
        `}</style>

        {/* Close Button */}
        <button
          onClick={handleClose}
          className={`absolute top-4 right-4 w-8 h-8 rounded-full flex items-center justify-center transition-colors ${
            isDarkMode 
              ? 'hover:bg-gray-800 text-gray-400 hover:text-white' 
              : 'hover:bg-gray-100 text-gray-500 hover:text-gray-700'
          }`}
        >
          <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M6 18L18 6M6 6l12 12"></path>
          </svg>
        </button>

        {/* Header */}
        <div className="text-center mb-4">
          <div className="w-12 h-12 mx-auto mb-2 bg-gradient-to-br from-purple-500 to-blue-600 rounded-xl flex items-center justify-center shadow-lg">
            <svg className="w-6 h-6 text-white" fill="none" stroke="currentColor" viewBox="0 0 24 24">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M9 12l2 2 4-4m5.618-4.016A11.955 11.955 0 0112 2.944a11.955 11.955 0 01-8.618 3.04A12.02 12.02 0 003 9c0 5.591 3.824 10.29 9 11.622 5.176-1.332 9-6.03 9-11.622 0-1.042-.133-2.052-.382-3.016z"></path>
            </svg>
          </div>
          <h2 className={`text-xl font-bold ${isDarkMode ? 'text-white' : 'text-gray-900'}`}>
            Complete Subscription Payment
          </h2>
          <p className={`text-sm ${isDarkMode ? 'text-gray-400' : 'text-gray-500'}`}>
            {plan.name} • Subscription #{subscriptionId?.slice(-12)?.toUpperCase()}
          </p>
        </div>

        {/* Plan Details */}
        <div className={`mb-4 p-4 rounded-xl ${isDarkMode ? 'bg-gray-800/50' : 'bg-gray-50'}`}>
          <div className="flex items-center justify-between mb-2">
            <span className={`text-sm font-medium ${isDarkMode ? 'text-gray-300' : 'text-gray-600'}`}>
              Plan
            </span>
            <span className={`text-sm font-semibold ${isDarkMode ? 'text-white' : 'text-gray-900'}`}>
              {plan.name}
            </span>
          </div>
          <div className="flex items-center justify-between mb-2">
            <span className={`text-sm font-medium ${isDarkMode ? 'text-gray-300' : 'text-gray-600'}`}>
              Duration
            </span>
            <span className={`text-sm font-semibold ${isDarkMode ? 'text-white' : 'text-gray-900'}`}>
              {plan.duration}
            </span>
          </div>
          <div className="flex items-center justify-between">
            <span className={`text-sm font-medium ${isDarkMode ? 'text-gray-300' : 'text-gray-600'}`}>
              Amount
            </span>
            <span className="text-2xl font-bold bg-gradient-to-r from-purple-600 to-blue-600 bg-clip-text text-transparent">
              ₹{plan.price}
            </span>
          </div>
        </div>

        {/* QR Code */}
        <div className="flex justify-center mb-4">
          <div className="relative">
            <div className="absolute inset-0 bg-gradient-to-r from-purple-400 to-blue-400 rounded-2xl blur-lg opacity-30"></div>
            <div className={`relative ${isDarkMode ? 'bg-gray-800' : 'bg-white'} p-3 rounded-2xl border ${isDarkMode ? 'border-gray-700' : 'border-gray-200'} shadow-lg`}>
              {qrValue && (
                <QRCode
                  value={qrValue}
                  size={160}
                  level="H"
                  bgColor={isDarkMode ? '#1F2937' : '#FFFFFF'}
                  fgColor="#000000"
                />
              )}
            </div>
          </div>
        </div>

        {/* UPI ID */}
        <div className={`rounded-xl p-3 mb-3 ${isDarkMode ? 'bg-gray-800/50' : 'bg-gray-50'}`}>
          <div className={`text-xs ${isDarkMode ? 'text-gray-400' : 'text-gray-600'} mb-2 text-center font-medium`}>
            Or pay to UPI ID
          </div>
          <div className="flex items-center gap-2">
            <code className={`flex-1 ${isDarkMode ? 'bg-gray-900 text-gray-300 border-gray-700' : 'bg-white text-gray-800 border-gray-200'} px-3 py-2 rounded-lg text-sm font-mono border text-center`}>
              {upiId}
            </code>
            <button
              onClick={handleCopy}
              className={`px-3 py-2 rounded-lg text-sm font-medium transition-all ${
                copied 
                  ? 'bg-green-500 text-white' 
                  : 'bg-gradient-to-r from-purple-500 to-blue-600 text-white hover:from-purple-600 hover:to-blue-700'
              }`}
            >
              {copied ? '✓' : 'Copy'}
            </button>
          </div>
        </div>

        {/* Instructions */}
        <div className={`rounded-xl p-3 mb-3 bg-gradient-to-br ${
          isDarkMode 
            ? 'from-purple-900/20 to-blue-900/20' 
            : 'from-purple-50 to-blue-50'
        }`}>
          <div className="flex items-center gap-2 mb-2">
            <div className="w-6 h-6 bg-gradient-to-r from-purple-500 to-blue-600 rounded-md flex items-center justify-center">
              <svg className="w-3 h-3 text-white" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M13 16h-1v-4h-1m1-4h.01M21 12a9 9 0 11-18 0 9 9 0 0118 0z"></path>
              </svg>
            </div>
            <span className={`font-semibold ${isDarkMode ? 'text-gray-200' : 'text-gray-800'} text-sm`}>
              How to Pay
            </span>
          </div>
          <ol className={`text-xs space-y-1 ${isDarkMode ? 'text-gray-300' : 'text-gray-700'}`}>
            <li className="flex items-start gap-1.5">
              <span className="w-4 h-4 bg-gradient-to-r from-purple-500 to-blue-600 text-white rounded-full flex items-center justify-center text-[10px] flex-shrink-0 mt-0.5">1</span>
              <span>Open UPI app</span>
            </li>
            <li className="flex items-start gap-1.5">
              <span className="w-4 h-4 bg-gradient-to-r from-purple-500 to-blue-600 text-white rounded-full flex items-center justify-center text-[10px] flex-shrink-0 mt-0.5">2</span>
              <span>Scan QR or enter ID</span>
            </li>
            <li className="flex items-start gap-1.5">
              <span className="w-4 h-4 bg-gradient-to-r from-purple-500 to-blue-600 text-white rounded-full flex items-center justify-center text-[10px] flex-shrink-0 mt-0.5">3</span>
              <span>Pay ₹{plan.price}</span>
            </li>
            <li className="flex items-start gap-1.5">
              <span className="w-4 h-4 bg-gradient-to-r from-purple-500 to-blue-600 text-white rounded-full flex items-center justify-center text-[10px] flex-shrink-0 mt-0.5">4</span>
              <span>Wait for admin verification</span>
            </li>
          </ol>
        </div>

        {/* Timer */}
        <div className="text-center mb-3">
          <div className={`inline-flex items-center gap-1.5 px-3 py-1.5 rounded-full ${
            countdown < 60 
              ? 'bg-red-100 text-red-700 dark:bg-red-900/30 dark:text-red-400' 
              : isDarkMode 
                ? 'bg-gray-800 text-gray-300' 
                : 'bg-gray-100 text-gray-600'
          }`}>
            <svg className="w-3.5 h-3.5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M12 8v4l3 3m6-3a9 9 0 11-18 0 9 9 0 0118 0z"></path>
            </svg>
            <span className="text-xs font-medium">Expires in {formatTime(countdown)}</span>
          </div>
        </div>

        {/* Waiting Message */}
        <div className={`rounded-xl p-3 ${
          isDarkMode 
            ? 'bg-yellow-900/20 border-yellow-800/50' 
            : 'bg-yellow-50 border-yellow-200'
        } border`}>
          <div className="flex items-center gap-2">
            <div className="w-8 h-8 bg-yellow-500 rounded-full flex items-center justify-center flex-shrink-0">
              <svg className="w-4 h-4 text-white animate-pulse" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M12 15v2m-6 4h12a2 2 0 002-2v-6a2 2 0 00-2-2H6a2 2 0 00-2 2v6a2 2 0 002 2zm10-10V7a4 4 0 00-8 0v4h8z"></path>
              </svg>
            </div>
            <div>
              <div className={`font-semibold ${isDarkMode ? 'text-yellow-300' : 'text-yellow-800'} text-sm`}>
                Waiting for Admin Verification
              </div>
              <div className={`text-xs ${isDarkMode ? 'text-yellow-400' : 'text-yellow-700'}`}>
                Your subscription will be activated after admin confirmation
              </div>
            </div>
          </div>
        </div>
      </div>

    {/* Toast Notification */}
    {toast && (
      <SubscriptionToast
        message={toast.message}
        type={toast.type}
        onClose={() => setToast(null)}
      />
    )}
  </div>
  );
};

export default SubscriptionQRCode;
